-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261124100000' and name='library_folder_drive')=1 then '예' else '아니오' end as value
union all select 'drive column nullable text with id shape check and per-workspace unique index',case when exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_library_folders') and attname='drive_folder_id' and not attisdropped and atttypid='text'::regtype and not attnotnull) and (select count(*) from pg_constraint where conrelid=to_regclass('public.app_library_folders') and conname='app_library_folders_drive_folder_check' and contype='c' and convalidated)=1 and exists(select 1 from pg_index i where i.indexrelid=to_regclass('public.app_library_folders_drive_folder_idx') and i.indisunique and i.indrelid=to_regclass('public.app_library_folders')) then '예' else '아니오' end
union all select 'set drive function: definer, empty search_path, no anon or PUBLIC execute',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_library_folder_set_drive(uuid,text,text)') and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'') !~ '(^|[{,])=') then '예' else '아니오' end
union all select 'set drive function: authenticated only',case when has_function_privilege('authenticated','public.app_library_folder_set_drive(uuid,text,text)','execute') and not has_function_privilege('service_role','public.app_library_folder_set_drive(uuid,text,text)','execute') then '예' else '아니오' end
union all select 'folders: no drive id write privilege for authenticated, none for anon',case when not has_column_privilege('authenticated','public.app_library_folders','drive_folder_id','insert,update') and not has_any_column_privilege('anon','public.app_library_folders','select,insert,update,references') then '예' else '아니오' end
union all select 'folders RLS on and no anon privilege',case when exists(select 1 from pg_class where oid=to_regclass('public.app_library_folders') and relrowsecurity) and not has_any_column_privilege('anon','public.app_library_folders','select,insert,update,references') then '예' else '아니오' end
union all select 'folders rows',(select count(*)::text from public.app_library_folders)
union all select 'folders grants policies triggers hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid=to_regclass('public.app_library_folders')),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_library_folders')),'')
  ||coalesce((select string_agg(t.tgname::text||':'||t.tgenabled::text||':'||t.tgfoid::regproc::text,',' order by t.tgname) from pg_trigger t where t.tgrelid=to_regclass('public.app_library_folders') and not t.tgisinternal),''));
